package com.ajay.amusezone.controller;
import com.ajay.amusezone.entity.WaterRide; import com.ajay.amusezone.repository.WaterRideRepository; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/water-rides") public class WaterRideController {private final WaterRideRepository r; public WaterRideController(WaterRideRepository r){this.r=r;} @GetMapping public List<WaterRide> all(){return r.findAll();} @GetMapping("/{id}") public WaterRide get(@PathVariable Long id){return r.findById(id).orElseThrow(()->new RuntimeException("Water ride not found"));} @PostMapping public WaterRide create(@RequestBody WaterRide x){return r.save(x);} @PutMapping("/{id}") public WaterRide update(@PathVariable Long id,@RequestBody WaterRide x){x.setId(id);return r.save(x);} @DeleteMapping("/{id}") public void delete(@PathVariable Long id){r.deleteById(id);}}
